using System.Security.Cryptography;
using FlowMind.Application.Interfaces;
using Microsoft.Extensions.Options;

namespace FlowMind.Infrastructure.Storage;

/// <summary>
/// Stores originals under {root}/{tenantId}/{documentId}/v{n}/original.{ext}.
/// File names on disk are generated by the server; user-supplied names are never used in paths.
/// </summary>
public sealed class LocalFileStorage
{
    private readonly string _root;

    public LocalFileStorage(IOptions<StorageOptions> options)
    {
        var root = options.Value.RootPath;
        if (string.IsNullOrWhiteSpace(root))
            throw new InvalidOperationException("Storage:RootPath is not configured.");
        _root = Path.GetFullPath(root);
        Directory.CreateDirectory(Path.Combine(_root, "_staging"));
    }

    public async Task<StagedFile> StageAsync(Stream content, long maxBytes, CancellationToken ct)
    {
        var temp = Path.Combine(_root, "_staging", Guid.NewGuid().ToString("N") + ".tmp");
        using var hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        long total = 0;
        try
        {
            await using var fs = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None, 81920, useAsync: true);
            var buffer = new byte[81920];
            int read;
            while ((read = await content.ReadAsync(buffer, ct)) > 0)
            {
                total += read;
                if (total > maxBytes) throw new InvalidDataException($"File exceeds the {maxBytes / (1024 * 1024)} MB limit.");
                hash.AppendData(buffer, 0, read);
                await fs.WriteAsync(buffer.AsMemory(0, read), ct);
            }
        }
        catch
        {
            TryDelete(temp);
            throw;
        }
        return new StagedFile(temp, Convert.ToHexString(hash.GetHashAndReset()).ToLowerInvariant(), total);
    }

    public string Commit(StagedFile staged, Guid tenantId, Guid documentId, int versionNumber, string extension)
    {
        var ext = extension.TrimStart('.').ToLowerInvariant();
        if (ext.Length is 0 or > 5 || !ext.All(char.IsLetterOrDigit)) throw new ArgumentException("Invalid extension.", nameof(extension));
        var relative = $"{tenantId:N}/{documentId:N}/v{versionNumber}/original.{ext}";   // forward slashes everywhere, so the same path works in every location
        CommitAt(staged, relative);
        return relative;
    }

    /// <summary>Moves a staged file to an exact relative path (used by Commit and when copying a file back from the cloud).</summary>
    public void CommitAt(StagedFile staged, string relative)
    {
        var full = Resolve(relative);
        Directory.CreateDirectory(Path.GetDirectoryName(full)!);
        File.Move(staged.TempPath, full, overwrite: true);
    }

    /// <summary>The real file path of a stored file (guaranteed to be inside the storage root).</summary>
    public string FullPath(string relative) => Resolve(relative);

    /// <summary>Removes a single stored file.</summary>
    public void DeleteFile(string relative)
    {
        var full = Resolve(relative);
        if (File.Exists(full)) File.Delete(full);
    }
    public void Discard(StagedFile staged) => TryDelete(staged.TempPath);

    public Stream OpenRead(string relativePath) =>
        new FileStream(Resolve(relativePath), FileMode.Open, FileAccess.Read, FileShare.Read, 81920, useAsync: true);

    public void DeleteDocument(Guid tenantId, Guid documentId)
    {
        var dir = Resolve(Path.Combine(tenantId.ToString("N"), documentId.ToString("N")));
        if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true);
    }

    public void DeleteTenant(Guid tenantId)
    {
        var dir = Resolve(tenantId.ToString("N"));   // built from a Guid only, and guaranteed to stay inside the storage root
        if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true);
    }

    public void DeleteVersion(Guid tenantId, Guid documentId, int versionNumber)
    {
        var dir = Resolve($"{tenantId:N}/{documentId:N}/v{versionNumber}");
        if (Directory.Exists(dir)) Directory.Delete(dir, recursive: true);
    }

    /// <summary>Resolves a relative path and guarantees it stays inside the storage root.</summary>
    private string Resolve(string relative)
    {
        var full = Path.GetFullPath(Path.Combine(_root, relative));
        if (!full.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("Path escapes the storage root.");
        return full;
    }

    private static void TryDelete(string path)
    {
        try { if (File.Exists(path)) File.Delete(path); } catch { /* best effort */ }
    }
}
